/**
 * `res_artifacts` — the METADATA of a stored blob, never the blob. The control plane records
 * what is about to be written, hands the worker a short-lived signed PUT, and never touches a
 * byte: no artifact ever travels through the API process (blueprint §5).
 *
 * Unlike its two siblings in this module, this table is NOT partitioned — one row per
 * artifact is orders of magnitude fewer rows than one per step — so it IS generated by
 * drizzle-kit, and `drizzle.config.ts` names this file explicitly. That is also why the FK
 * target is imported from the orchestration FACADE rather than reached for directly: the DAG
 * allows results → orchestration, and a composite FK is the one thing that makes "an artifact
 * on another team's job" unrepresentable rather than merely unchecked.
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  check,
  foreignKey,
  index,
  integer,
  pgPolicy,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { appRole } from "../../kernel/index.js";
import { jobRuns } from "../../orchestration/index.js";

/** Identical to every other tenant predicate in the system. NULLIF is not optional: `RESET
 * app.team_id` leaves an EMPTY STRING behind, and `''::uuid` throws 22P02 instead of failing closed. */
const tenantPredicate = sql`team_id = NULLIF(current_setting('app.team_id', true), '')::uuid`;

/**
 * The closed set of things a worker may upload, published verbatim in the fleet contract. It
 * lives HERE, next to the table, so the CHECK constraint below is BUILT from it: the type and
 * the column cannot drift, and adding a sixth kind is one edit plus one migration.
 */
export const ARTIFACT_KINDS = [
  "trace",
  "screenshot",
  "screenshot_bundle",
  "video",
  "log",
] as const;
export type ArtifactKind = (typeof ARTIFACT_KINDS)[number];

/**
 * Two states, and the transition only ever goes one way. `pending` means "a URL was signed";
 * `uploaded` means "the worker told us the bytes landed" (Task 13, from the `screenshot` event
 * or the `artifacts[]` of `complete`). A `pending` row whose bytes never arrive is the record
 * of a failed upload, which is exactly what an operator needs to see.
 */
export const ARTIFACT_STATUSES = ["pending", "uploaded"] as const;
export type ArtifactStatus = (typeof ARTIFACT_STATUSES)[number];

/**
 * Per-artifact ceiling, 2GiB-1. A trace larger than this is a bug in the worker's ring buffer,
 * not a big test — and signing it would let one run fill the store.
 *
 * The column is `bigint` even though the cap fits int4 exactly: the cap is a POLICY and the
 * column is PHYSICS. Raising the ceiling later is then one CHECK, not an ALTER TYPE on the
 * table every result page joins against.
 */
export const ARTIFACT_MAX_BYTES = 2_147_483_647;

/** Compile-time constants only — `sql.raw` is what inlines them into the DDL drizzle-kit emits. */
const artifactKindList = ARTIFACT_KINDS.map((k) => `'${k}'`).join(",");
const artifactStatusList = ARTIFACT_STATUSES.map((s) => `'${s}'`).join(",");

export const resArtifacts = pgTable(
  "res_artifacts",
  {
    teamId: uuid("team_id").notNull(),
    id: uuid("id").primaryKey().defaultRandom(),
    jobRunId: uuid("job_run_id").notNull(),
    /** An infra retry re-uploads everything, so the attempt is part of the object key too. */
    attempt: integer("attempt").notNull(),
    kind: text("kind").notNull(),
    /**
     * The path inside the bucket, STARTING WITH THE TEAM ID. It is stored rather than
     * recomputed because retention and lifecycle rules read it, and because the signature the
     * worker holds covers this exact string — a key recomputed from a changed formula would
     * silently stop matching the object it named.
     */
    objectKey: text("object_key").notNull(),
    contentType: text("content_type").notNull(),
    sizeBytes: bigint("size_bytes", { mode: "number" }).notNull(),
    /** Lowercase hex of the SHA-256 the worker computed. What `complete` matches a blob by. */
    sha256: text("sha256").notNull(),
    status: text("status").notNull().default("pending"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    uploadedAt: timestamp("uploaded_at", { withTimezone: true }),
  },
  (t) => [
    unique("res_artifacts_team_id_unique").on(t.teamId, t.id),
    index("res_artifacts_team_job_idx").on(t.teamId, t.jobRunId, t.attempt),
    foreignKey({
      name: "res_artifacts_job_fk",
      columns: [t.teamId, t.jobRunId],
      foreignColumns: [jobRuns.teamId, jobRuns.id],
    }),
    check("res_artifacts_attempt_check", sql`${t.attempt} >= 1`),
    check("res_artifacts_kind_check", sql`${t.kind} IN (${sql.raw(artifactKindList)})`),
    check("res_artifacts_status_check", sql`${t.status} IN (${sql.raw(artifactStatusList)})`),
    check(
      "res_artifacts_size_check",
      sql`${t.sizeBytes} >= 0 AND ${t.sizeBytes} <= ${sql.raw(String(ARTIFACT_MAX_BYTES))}`,
    ),
    pgPolicy("tenant_isolation", {
      as: "permissive",
      for: "all",
      to: appRole,
      using: tenantPredicate,
      withCheck: tenantPredicate,
    }),
  ],
).enableRLS();
